// Generates src/Rizzy.Htmx/HtmxAssets.g.cs from the installed htmx.org package: the htmx version
// Rizzy is tested with and SRI hashes for htmx and every official extension file, which
// <RzScripts /> uses for jsDelivr URLs. Run after changing the htmx.org dev dependency:
//   npm run generate:htmx-assets
// tests/htmx4-coverage.test.mjs fails when the generated file is out of date.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.resolve(here, '..');
const htmxRoot = path.join(packageRoot, 'node_modules', 'htmx.org');
const outFile = path.resolve(packageRoot, '../../src/Rizzy.Htmx/HtmxAssets.g.cs');

export function computeAssets() {
    const version = JSON.parse(fs.readFileSync(path.join(htmxRoot, 'package.json'), 'utf8')).version;
    const dist = path.join(htmxRoot, 'dist');
    const files = ['htmx.js', 'htmx.min.js'];
    for (const f of fs.readdirSync(path.join(dist, 'ext')).sort()) {
        if (f.endsWith('.js')) files.push(`ext/${f}`);
    }
    const hashes = files.map((f) => [f, 'sha384-' + crypto.createHash('sha384')
        .update(fs.readFileSync(path.join(dist, f))).digest('base64')]);
    return { version, hashes };
}

export function render({ version, hashes }) {
    const entries = hashes.map(([f, h]) => `        ["${f}"] = "${h}",`).join('\n');
    return `// <auto-generated>
// Generated by packages/rizzy/scripts/generate-htmx-assets.mjs from htmx.org ${version}.
// Do not edit by hand: run \`npm run generate:htmx-assets\` in packages/rizzy.
// </auto-generated>
namespace Rizzy.Htmx;

/// <summary>The htmx version Rizzy is tested with, and subresource integrity hashes for its files.</summary>
public static class HtmxAssets
{
    /// <summary>The htmx version Rizzy is built and tested against.</summary>
    public const string Version = "${version}";

    /// <summary>jsDelivr URL of htmx's <c>dist/</c> folder for <see cref="Version"/>.</summary>
    public const string CdnBaseUrl = "https://cdn.jsdelivr.net/npm/htmx.org@${version}/dist/";

    /// <summary>SHA-384 integrity hashes keyed by file path under <c>dist/</c> (for example <c>ext/hx-sse.min.js</c>).</summary>
    public static IReadOnlyDictionary<string, string> Integrity { get; } = new Dictionary<string, string>(StringComparer.Ordinal)
    {
${entries}
    };
}
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    const content = render(computeAssets());
    fs.writeFileSync(outFile, content.replace(/\r?\n/g, '\n'));
    console.log(`Wrote ${path.relative(process.cwd(), outFile)}`);
}
